266: function drawTopoMap() {
267:   const map = document.getElementById('topoMap');
268:   if (!map || document.getElementById('mapOverlay').hidden) return;
269: 
270:   const rect = map.getBoundingClientRect();
271:   if (!rect.width || !rect.height) return;
272:   const ratio = window.devicePixelRatio || 1;
273:   const pixelWidth = Math.round(rect.width * ratio);
274:   const pixelHeight = Math.round(rect.height * ratio);
275:   if (map.width !== pixelWidth || map.height !== pixelHeight) {
276:     map.width = pixelWidth;
277:     map.height = pixelHeight;
278:   }
279:   const mapCtx = map.getContext('2d');
280:   mapCtx.setTransform(ratio, 0, 0, ratio, 0, 0);
281:   mapCtx.clearRect(0, 0, rect.width, rect.height);
282:   mapCtx.fillStyle = '#28382d';
283:   mapCtx.fillRect(0, 0, rect.width, rect.height);
284: 
285:   const padding = 28;
286:   const scale = Math.min((rect.width - padding * 2) / world.width, (rect.height - padding * 2) / world.height);
287:   const offsetX = (rect.width - world.width * scale) / 2;
288:   const offsetY = (rect.height - world.height * scale) / 2;
289:   mapCtx.save();
290:   mapCtx.translate(offsetX, offsetY);
291:   mapCtx.scale(scale, scale);
292: 
293:   // Soft contour bands make the full-world overview read as a field map.
294:   mapCtx.strokeStyle = 'rgba(190, 202, 158, 0.19)';
295:   mapCtx.lineWidth = 1.2 / scale;
296:   [[370, 420, 230], [770, 1080, 280], [1450, 380, 330], [1580, 1280, 260]].forEach(([cx, cy, radius]) => {
297:     for (let ring = 1; ring <= 5; ring += 1) {
298:       mapCtx.beginPath();
299:       mapCtx.ellipse(cx, cy, radius * ring * 0.34, radius * ring * 0.25, -0.3, 0, Math.PI * 2);
300:       mapCtx.stroke();
301:     }
302:   });
303: 
304:   mapCtx.strokeStyle = '#4d8ba1';
305:   mapCtx.lineWidth = 22;
306:   mapCtx.lineCap = 'round';
307:   mapCtx.lineJoin = 'round';
308:   mapCtx.beginPath();
309:   world.river.forEach((point, index) => index ? mapCtx.lineTo(point.x, point.y) : mapCtx.moveTo(point.x, point.y));
310:   mapCtx.stroke();
311:   mapCtx.setLineDash([12, 12]);
312:   mapCtx.strokeStyle = 'rgba(190, 229, 232, .8)';
313:   mapCtx.lineWidth = 2;
314:   mapCtx.stroke();
315:   mapCtx.setLineDash([]);
316: 
317:   mapCtx.strokeStyle = '#18221b';
318:   mapCtx.lineWidth = 30;
319:   mapCtx.beginPath();
320:   world.route.forEach((point, index) => index ? mapCtx.lineTo(point.x, point.y) : mapCtx.moveTo(point.x, point.y));
321:   mapCtx.stroke();
322:   mapCtx.strokeStyle = '#d7d4be';
323:   mapCtx.lineWidth = 18;
324:   mapCtx.stroke();
325:   mapCtx.setLineDash([18, 12]);
326:   mapCtx.strokeStyle = '#8f9a77';
327:   mapCtx.lineWidth = 2;
328:   mapCtx.stroke();
329:   mapCtx.setLineDash([]);
330: 
331:   missionStops.forEach((stop, index) => {
332:     mapCtx.beginPath();
333:     mapCtx.fillStyle = state.objectiveCompleted[index] ? '#899582' : index === state.missionIndex ? '#d6e35a' : '#d7d4be';
334:     mapCtx.arc(stop.x, stop.y, index === state.missionIndex && !state.objectiveCompleted[index] ? 15 : 10, 0, Math.PI * 2);
335:     mapCtx.fill();
336:     mapCtx.strokeStyle = '#1b251e';
337:     mapCtx.lineWidth = 3;
338:     mapCtx.stroke();
339:     mapCtx.font = `${18 / scale}px 'DM Mono', monospace`;
340:     mapCtx.fillStyle = '#e7e9de';
341:     mapCtx.fillText(stop.label.toUpperCase(), stop.x + 22, stop.y - 16);
342:   });
343: 
344:   mapCtx.save();
345:   mapCtx.translate(player.x, player.y);
346:   mapCtx.rotate(player.dir);
347:   mapCtx.fillStyle = '#c0dc68';
348:   mapCtx.strokeStyle = '#152019';
349:   mapCtx.lineWidth = 4;
350:   mapCtx.beginPath();
351:   mapCtx.moveTo(20, 0);
352:   mapCtx.lineTo(-13, -12);
353:   mapCtx.lineTo(-9, 0);
354:   mapCtx.lineTo(-13, 12);
355:   mapCtx.closePath();
356:   mapCtx.fill();
357:   mapCtx.stroke();
358:   mapCtx.restore();
359:   mapCtx.restore();
360: }
