453: function checkMission() {
454:   for (let i = 0; i < missionStops.length; i += 1) {
455:     const stop = missionStops[i];
456:     const dist = distanceToPoint(player, stop);
457:     if (!state.objectiveCompleted[i] && dist < stop.radius) {
458:       state.objectiveCompleted[i] = true;
459:       if (i === 0) showToast('OLD LOGGING ROAD SECURED');
460:       if (i === 1) showToast('BOG LINE CROSSED');
461:       if (i === 2) showToast('RIDGE BEACON REACHED');
462:       state.missionIndex = Math.min(i + 1, missionStops.length - 1);
463:       break;
464:     }
465:   }
466: 
467:   if (state.objectiveCompleted.every(Boolean)) {
468:     showToast('MISSION COMPLETE — CALL IN THE CREW', 2200);
469:   }
470: 
471:   updateMission();
472: }
